arguments.command:
cd /tmp && mkdir -p stackalloc_test && cat > stackalloc_test/Program.cs << 'EOF'
using System;

Span<nint> a = stackalloc nint[4];
a[0] = 42;
a[1] = nint.MaxValue;
Console.WriteLine($"Span<nint> stackalloc works! Length={a.Length}, a[0]={a[0]}, a[1]={a[1]}");

Span<nuint> b = stackalloc nuint[3];
b[0] = nuint.MaxValue;
Console.WriteLine($"Span<nuint> stackalloc works! Length={b.Length}, b[0]={b[0]}");
EOF
cat > stackalloc_test/stackalloc_test.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
  </PropertyGroup>
</Project>
EOF
dotnet run --project stackalloc_test 2>&1

